getcontext().prec = 2000

def fmt(d):
    s = format(d, 'f')
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s in ('-0', ''):
        s = '0'
    return s

groups = {}
with open('дані/виміри.csv', encoding='utf-8-sig', newline='') as f:
    reader = csv.reader(f)
    next(reader, None)
    for row in reader:
        if not row:
            continue
        name = row[0].strip()
        val = row[1].strip() if len(row) > 1 else ''
        lst = groups.setdefault(name, [])
        if val != '':
            lst.append(Decimal(val))

for name in sorted(groups):
    vals = sorted(groups[name])
    n = len(vals)
    if n == 0:
        print(f"{name}: —")
        continue
    if n % 2:
        med = vals[n // 2]
    else:
        med = (vals[n // 2 - 1] + vals[n // 2]) / 2
